<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireLogin();$db=Database::getInstance()->pdo();$st=$db->prepare('SELECT s.*,c.name customer,u.full_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id JOIN users u ON u.id=s.user_id WHERE s.id=?');$st->execute(array((int)$_GET['id']));$sale=$st->fetch();if(!$sale){http_response_code(404);exit('الفاتورة غير موجودة');}$st=$db->prepare('SELECT * FROM sale_items WHERE sale_id=?');$st->execute(array($sale['id']));$items=$st->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>فاتورة <?= Helper::e($sale['invoice_no']) ?></title><style>body{font:14px Tahoma,Arial;max-width:380px;margin:20px auto;color:#222}.center{text-align:center}.row{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px dashed #ccc}button{padding:8px 18px}@media print{button{display:none}body{margin:0}}</style></head><body><div class="center"><h2><?= Helper::e(APP_NAME) ?></h2><div>فاتورة بيع</div></div><hr><div>رقم: <?= Helper::e($sale['invoice_no']) ?></div><div>التاريخ: <?= Helper::e($sale['created_at']) ?></div><div>الكاشير: <?= Helper::e($sale['full_name']) ?></div><?php if($sale['customer']): ?><div>الزبون: <?= Helper::e($sale['customer']) ?></div><?php endif; ?><hr><?php foreach($items as $it): ?><div class="row"><span><?= Helper::e($it['product_name']) ?> × <?= Helper::e($it['quantity']) ?></span><span><?= number_format($it['unit_price']*$it['quantity'],2) ?></span></div><?php endforeach; ?><div class="row"><strong>المجموع</strong><strong><?= Helper::money($sale['total']) ?></strong></div><div class="row"><span>المدفوع</span><span><?= Helper::money($sale['paid']) ?></span></div><div class="center"><p>شكراً لزيارتكم ☕</p><button onclick="window.print()">طباعة</button> <a href="<?= APP_URL ?>/modules/sales/pos.php">بيع جديد</a></div></body></html>
